import * as React from 'react';
import { cn } from '@/lib/utils';

export type TestimonialProps = React.HTMLAttributes<HTMLElement> & {
  /** The testimonial copy, without quotation marks. */
  quote: string;
  /** Person or company name. */
  name: string;
  /** Role or title. */
  role?: string;
  /** Company name. */
  company?: string;
  /** Avatar slot (usually Avatar). */
  avatar?: React.ReactNode;
  /** Brand or logo slot shown in the card header. */
  logo?: React.ReactNode;
  /** Card surface or plain quote. Default 'card'. */
  variant?: 'card' | 'plain';
  /** Quote scale. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
};

const quoteSizes = {
  sm: 'text-base',
  md: 'text-lg',
  lg: 'text-xl sm:text-2xl',
} as const;

/**
 * Semantic testimonial: figure + blockquote + figcaption. Use it for written
 * proof on landing and review pages, not for app feedback prompts.
 */
export const Testimonial = React.forwardRef<HTMLElement, TestimonialProps>(function Testimonial(
  { quote, name, role, company, avatar, logo, variant = 'card', size = 'md', className, ...props },
  ref
) {
  return (
    <figure
      ref={ref as never}
      className={cn(
        'flex h-full flex-col gap-5',
        variant === 'card' && 'rounded-xl border border-border bg-card p-6 shadow-sm',
        className
      )}
      {...props}
    >
      {logo && <div className="flex items-center">{logo}</div>}
      <blockquote className={cn('flex-1 leading-relaxed', quoteSizes[size])}>
        <p>“{quote}”</p>
      </blockquote>
      <figcaption className="flex items-center gap-3">
        {avatar && <div className="shrink-0">{avatar}</div>}
        <div className="min-w-0">
          <p className="text-sm font-semibold">{name}</p>
          {(role || company) && (
            <p className="text-xs text-muted-foreground">
              {[role, company].filter(Boolean).join(', ')}
            </p>
          )}
        </div>
      </figcaption>
    </figure>
  );
});

{
  "id": "testimonial",
  "name": "Testimonial",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.1",
  "sourceDir": "testimonial",
  "exportName": "Testimonial",
  "description": "Semantic written testimonial with quote, person, role, company, avatar and logo slots.",
  "designIntent": "Review and landing pages repeat the same quote hierarchy. Testimonial uses figure, blockquote and figcaption so the attribution is real structure instead of three styled paragraphs.",
  "props": [
    {
      "name": "quote",
      "type": "string",
      "required": true,
      "description": "Testimonial copy without quotation marks."
    },
    {
      "name": "name",
      "type": "string",
      "required": true,
      "description": "Person or company name."
    },
    {
      "name": "role",
      "type": "string",
      "required": false,
      "description": "Role or title."
    },
    {
      "name": "company",
      "type": "string",
      "required": false,
      "description": "Company name."
    },
    {
      "name": "avatar",
      "type": "ReactNode",
      "required": false,
      "description": "Avatar slot, usually Avatar."
    },
    {
      "name": "logo",
      "type": "ReactNode",
      "required": false,
      "description": "Brand or logo slot shown in the card header."
    },
    {
      "name": "variant",
      "type": "'card' | 'plain'",
      "required": false,
      "defaultValue": "card",
      "enum": [
        "card",
        "plain"
      ],
      "description": "Card surface or plain quote."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "enum": [
        "sm",
        "md",
        "lg"
      ],
      "description": "Quote scale."
    }
  ],
  "examples": [
    {
      "title": "Written testimonial",
      "code": "<Testimonial\n  quote=\"The right advisor changed the outcome.\"\n  name=\"Bob Falahee\"\n  role=\"CEO\"\n  company=\"Blind & Shade\"\n  avatar={<Avatar><AvatarFallback>BF</AvatarFallback></Avatar>}\n/>",
      "description": "A card testimonial with attribution."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't add quotation marks in the quote prop",
      "explanation": "The component renders the quotation marks. Duplicating them produces doubled punctuation.",
      "example": "// Avoid\nquote=\"\\\"Quote\\\"\""
    }
  ],
  "accessibility": [
    {
      "feature": "Quote semantics",
      "implementation": "Renders figure, blockquote and figcaption",
      "userRequirements": "Keep the person name in the figcaption"
    },
    {
      "feature": "Avatar alternative",
      "implementation": "Avatar is a slot",
      "userRequirements": "Use an avatar with a fallback and avoid a redundant alt text"
    }
  ],
  "compositionRules": [
    {
      "component": "Grid",
      "relationship": "Place several testimonials in a Grid for a quote wall",
      "example": "<Grid mdCols={3} gap=\"lg\"><Testimonial ... /></Grid>"
    }
  ],
  "relatedComponents": [
    "Card",
    "Avatar",
    "Quote",
    "Grid"
  ]
}
